import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen0Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private JavaType baseType;
    private BeanProperty property;
    private Map<String, JsonDeserializer<Object>> deserializers;
    private TestTypeDeserializer testDeserializer;

    // Concrete implementation for testing protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                      boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override
        public String baseTypeName() { return "Test"; }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return null;
        }

        @Override
        protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId) throws IOException {
            return null;
        }

        // Expose protected method for testing
        public JsonDeserializer<Object> publicFindDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializer(ctxt, typeId);
        }

        // Helper to inject state for testing
        public void setDeserializers(Map<String, JsonDeserializer<Object>> deserializers) {
            this.deserializers = deserializers;
        }

        // We need to override the internal field access if possible, but since it's private/protected 
        // in the real class, we use the constructor logic or reflection if needed. 
        // For this test, we'll assume we can manipulate the state via the class structure provided.
    }

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        baseType = mock(JavaType.class);
        property = mock(BeanProperty.class);
        deserializers = new HashMap<>();

        // Mock TypeFactory for specialized type construction
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        when(ctxt.getTypeFactory()).thenReturn(typeFactory);

        testDeserializer = new TestTypeDeserializer(baseType, idResolver, "type", true, null);
        // Use reflection to inject the private _deserializers map to control the test
        try {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            field.setAccessible(true);
            field.set(testDeserializer, deserializers);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Inject property
        try {
            java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
            propField.setAccessible(true);
            propField.set(testDeserializer, property);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testFindDeserializer_ExistingInMap() throws IOException {
        JsonDeserializer<Object> existing = mock(JsonDeserializer.class);
        deserializers.put("myType", existing);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, "myType");

        assertEquals(existing, result);
        verifyNoInteractions(idResolver);
    }

    @Test
    public void testFindDeserializer_TypeIdFound_NoGeneric() throws IOException {
        String typeId = "StringClass";
        JavaType type = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(type.getRawClass()).thenReturn(String.class);
        when(type.hasGenericTypes()).thenReturn(false);
        when(type.getClass()).thenReturn(type.getClass()); 
        when(ctxt.findContextualValueDeserializer(any(JavaType.class), eq(property))).thenReturn(expectedDeser);

        // Mock baseType behavior for the class check
        when(baseType.getClass()).thenReturn(type.getClass());

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
        assertEquals(expectedDeser, deserializers.get(typeId));
    }

    @Test
    public void testFindDeserializer_TypeIdFound_WithGenerics() throws IOException {
        String typeId = "ListClass";
        JavaType type = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(type.hasGenericTypes()).thenReturn(true);
        when(type.getClass()).thenReturn(type.getClass());
        when(baseType.getClass()).thenReturn(type.getClass());
        when(ctxt.findContextualValueDeserializer(eq(type), eq(property))).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNotFound_DefaultImplFound() throws IOException {
        String typeId = "Unknown";
        JsonDeserializer<Object> defaultDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        // We need to override _findDefaultImplDeserializer in our test class to return something
        testDeserializer = new TestTypeDeserializer(baseType, idResolver, "type", true, null) {
            @Override
            protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) {
                return defaultDeser;
            }
        };
        // Re-inject fields because we created a new instance
        try {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            field.setAccessible(true);
            field.set(testDeserializer, deserializers);
            java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
            propField.setAccessible(true);
            propField.set(testDeserializer, property);
        } catch (Exception e) {}

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertEquals(defaultDeser, result);
        assertEquals(defaultDeser, deserializers.get(typeId));
    }

    @Test
    public void testFindDeserializer_TypeIdNotFound_DefaultNull_HandleUnknownFound() throws IOException {
        String typeId = "Unknown";
        JavaType actualType = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        testDeserializer = new TestTypeDeserializer(baseType, idResolver, "type", true, null) {
            @Override
            protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) {
                return null;
            }
            @Override
            protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId) {
                return actualType;
            }
        };
        try {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            field.setAccessible(true);
            field.set(testDeserializer, deserializers);
            java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
            propField.setAccessible(true);
            propField.set(testDeserializer, property);
        } catch (Exception e) {}

        when(ctxt.findContextualValueDeserializer(eq(actualType), eq(property))).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testFindDeserializer_TypeIdNotFound_DefaultNull_HandleUnknownNull_ReturnsNull() throws IOException {
        String typeId = "Unknown";

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        testDeserializer = new TestTypeDeserializer(baseType, idResolver, "type", true, null) {
            @Override
            protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) {
                return null;
            }
            @Override
            protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId) {
                return null;
            }
        };
        try {
            java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
            field.setAccessible(true);
            field.set(testDeserializer, deserializers);
            java.lang.reflect.Field propField = TypeDeserializerBase.class.getDeclaredField("_property");
            propField.setAccessible(true);
            propField.set(testDeserializer, property);
        } catch (Exception e) {}

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertNull(result);
    }

    @Test
    public void testFindDeserializer_BaseTypeMismatch() throws IOException {
        String typeId = "DifferentType";
        JavaType type = mock(JavaType.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(type.getClass()).thenReturn(type.getClass());
        // Make baseType class different from type class
        when(baseType.getClass()).thenReturn(Object.class); 
        when(ctxt.findContextualValueDeserializer(eq(type), eq(property))).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = testDeserializer.publicFindDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }
}
